using Jindan.Contracts;
using Jindan.Core;
using Jindan.Core.Sync;
using Jindan.Infrastructure;
using System.Text.Json;
using System.Text.Json.Nodes;

static partial class Program
{
    static string root = "", work = ""; static int pass, fail; static readonly List<object> results = [];
    static void Check(bool ok, string message = "Assertion failed") { if (!ok) throw new Exception(message); }
    static async Task Expect(string code, Func<Task> run) { try { await run(); } catch (WorkspaceException e) { Check(e.Code == code, "Expected " + code + ", got " + e.Code); return; } throw new Exception("Expected " + code); }
    static async Task Cancelled(Task task) { try { await task; } catch (OperationCanceledException) { return; } throw new Exception("Expected cancellation"); }
    static void Schemas(LocalWorkspace w) { w.RegisterSchema(new("projects", "Project", [new("name", "Name", Required: true)], false)); w.RegisterSchema(new("processes", "Process", [new("name", "Name", Required: true)], true)); w.RegisterSchema(new("tasks", "Task", [new("name", "Name", Required: true), new("relatedProjectId", "Project")], false)); w.RegisterSchema(new("board", "Board", [new("name", "Name", Required: true)], false)); }
    static RecordDraft Draft(string kind, string name, string? project = null) => new(null, kind, project, 0, new() { ["name"] = name });
    static async Task<(LocalWorkspace W, Identity A)> Setup(string name) { var w = new LocalWorkspace(Path.Combine(work, name)); Schemas(w); return (w, await w.BootstrapAsync("Local owner", "synthetic-password-70", true)); }
    static async Task Run(string name, Func<Task> test) { try { await test(); pass++; results.Add(new { name, pass = true }); Console.WriteLine("PASS " + name); } catch (Exception e) { fail++; results.Add(new { name, pass = false, error = e.GetType().Name, message = e.Message }); Console.WriteLine("FAIL " + name + " " + e.Message); } }
    public static async Task<int> Main(string[] args)
    {
        root = args.FirstOrDefault() ?? Directory.GetCurrentDirectory(); work = Path.Combine(root, "artifacts/workspace-sync70", DateTime.UtcNow.ToString("yyyyMMddTHHmmss") + "-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(work);
        await Run("actual feature saves atomically queue projects processes and personal tasks; other kinds excluded", async () => { var (w, a) = await Setup("kinds"); using (w) using (var sync = new WorkspaceSyncService(w, a)) { var p = await w.SaveAsync(a, Draft("projects", "P")); await w.SaveAsync(a, Draft("processes", "Process", p.Id)); await w.SaveAsync(a, Draft("tasks", "Task")); await w.SaveAsync(a, Draft("board", "Board")); var s = await sync.StatusAsync(); Check(s.Pending.Count == 3 && !s.Configured && !s.ProductionVerified && s.Pending.Single(e => e.Kind == "tasks").ProjectId is null); } });
        await Run("latest save coalesces and logical deletion commits tombstone revision in same state", async () => { var (w, a) = await Setup("coalesce"); using (w) using (var sync = new WorkspaceSyncService(w, a)) { var p = await w.SaveAsync(a, Draft("projects", "P")); var first = (await sync.StatusAsync()).Pending.Single(); var updated = await w.SaveAsync(a, new(p.Id, p.Kind, null, p.Revision, new() { ["name"] = "P2" })); var second = (await sync.StatusAsync()).Pending.Single(); Check(first.Revision != second.Revision && second.RecordRevision == updated.Revision); await w.DeleteAsync(a, p.Kind, p.Id, updated.Revision, true); var final = (await sync.StatusAsync()).Pending.Single(); Check(final.Operation == "delete" && final.RecordRevision == updated.Revision + 1); } });
        await Run("feature and queue restart together and forged sessions cannot read queue", async () => { var (w, a) = await Setup("restart"); var p = await w.SaveAsync(a, Draft("projects", "P")); var path = w.DataRoot; w.Dispose(); using var reopened = new LocalWorkspace(path); Schemas(reopened); var actor = await reopened.LoginAsync("Local owner", "synthetic-password-70"); using var sync = new WorkspaceSyncService(reopened, actor); Check((await sync.StatusAsync()).Pending.Single().Id == p.Id); using var fake = new WorkspaceSyncService(reopened, actor with { }); await Expect("UNAUTHENTICATED", () => fake.StatusAsync()); });
        await Run("legacy schema1 with no queue opens without retroactively uploading prior records", async () => { var (w, a) = await Setup("legacy"); await w.SaveAsync(a, Draft("projects", "Old local")); var path = w.DataRoot; w.Dispose(); var file = Path.Combine(path, "workspace.json"); var doc = JsonNode.Parse(File.ReadAllText(file))!.AsObject(); doc.Remove("SyncOutbox"); doc.Remove("LastSyncAcknowledgedAt"); File.WriteAllText(file, doc.ToJsonString()); using var old = new LocalWorkspace(path); Schemas(old); var actor = await old.LoginAsync("Local owner", "synthetic-password-70"); using var sync = new WorkspaceSyncService(old, actor); Check((await old.ListAsync(actor, new RecordQuery("projects"))).Count == 1 && (await sync.StatusAsync()).Pending.Count == 0); });
        await Run("production NotConfigured and missing confirmation retain all pending mutations", async () => { var (w, a) = await Setup("blocked"); using (w) using (var sync = new WorkspaceSyncService(w, a)) { await w.SaveAsync(a, Draft("projects", "P")); await Expect("CONFIRMATION", () => sync.PushPendingAsync(null, false)); await Expect("PRODUCTION_NOT_CONFIGURED", () => sync.PushPendingAsync(null, true)); Check((await sync.StatusAsync()).Pending.Count == 1); } });
        await Run("synthetic transport requires deliberate service opt-in; authenticated synthetic push acknowledged", async () => { var (w, a) = await Setup("optin"); using (w) { var p = await w.SaveAsync(a, Draft("projects", "P")); var adapter = new IsolatedLoopbackSyncAdapter([new(a.Id, p.Id)], true); using (var blocked = new WorkspaceSyncService(w, a, adapter)) { Check(!(await blocked.StatusAsync()).Configured); await Expect("TEST_FIXTURE_NOT_ENABLED", () => blocked.PushPendingAsync(p.Id, true)); } using var sync = new WorkspaceSyncService(w, a, adapter, true); var result = await sync.PushPendingAsync(p.Id, true); Check(result.Acknowledged == 1 && result.IsSynthetic && !result.ProductionVerified && (await sync.StatusAsync()).Pending.Count == 0); } });
        await Run("per-project push excludes other project and personal queue", async () => { var (w, a) = await Setup("project"); using (w) { var p = await w.SaveAsync(a, Draft("projects", "P")); var q = await w.SaveAsync(a, Draft("projects", "Q")); await w.SaveAsync(a, Draft("tasks", "Personal")); var adapter = new IsolatedLoopbackSyncAdapter([new(a.Id, p.Id)], true); using var sync = new WorkspaceSyncService(w, a, adapter, true); Check((await sync.StatusAsync(p.Id)).Pending.Count == 1); await sync.PushPendingAsync(p.Id, true); var rest = (await sync.StatusAsync()).Pending; Check(rest.Count == 2 && rest.Any(e => e.Id == q.Id) && rest.Any(e => e.Kind == "tasks")); } });
        await Run("current persisted project membership and role rechecked, not identity record claims", async () => { var (w, a) = await Setup("membership"); using (w) { var p = await w.SaveAsync(a, Draft("projects", "P")); var user = await w.SaveUserAsync(a, null, "Editor", "editor", [p.Id], false, "editor-password-70"); var e = await w.LoginAsync("Editor", "editor-password-70"); await w.SaveAsync(e, Draft("processes", "Own", p.Id)); var adapter = new IsolatedLoopbackSyncAdapter([new(e.Id, p.Id)], true); using var sync = new WorkspaceSyncService(w, e, adapter, true); await w.SaveUserAsync(a, user.Id, "Editor", "viewer", [p.Id], false, null); await Expect("FORBIDDEN", () => sync.PushPendingAsync(p.Id, true)); await w.SaveUserAsync(a, user.Id, "Editor", "editor", [], false, null); await Expect("FORBIDDEN", () => sync.StatusAsync(p.Id)); Check(adapter.DeliveryAttempts == 0); } });
        await Run("admin does not silently upload other editor queue; personal tasks scoped to actor", async () => { var (w, a) = await Setup("users"); using (w) { await w.SaveUserAsync(a, null, "Editor", "editor", [], false, "editor-password-70"); var e = await w.LoginAsync("Editor", "editor-password-70"); var t = await w.SaveAsync(e, Draft("tasks", "Private")); using var admin = new WorkspaceSyncService(w, a); Check((await admin.StatusAsync()).Pending.Count == 0); var adapter = new IsolatedLoopbackSyncAdapter([new(e.Id, "personal:" + e.Id)], true); using var user = new WorkspaceSyncService(w, e, adapter, true); Check((await user.PushPendingAsync(null, true)).Acknowledged == 1); Check((await adapter.FetchAsync(new(e.Id, "personal:" + e.Id), SyncTable.Tasks, default)).Records.Single().Id == t.Id); } });
        await Run("old ACK after feature edit cannot erase new local revision", async () => { var (w, a) = await Setup("race"); using (w) { var p = await w.SaveAsync(a, Draft("projects", "P")); var entered = new TaskCompletionSource(); var release = new TaskCompletionSource(); var adapter = new IsolatedLoopbackSyncAdapter([new(a.Id, p.Id)], true) { BeforePush = async (_, ct) => { entered.SetResult(); await release.Task.WaitAsync(ct); } }; using var sync = new WorkspaceSyncService(w, a, adapter, true); var pushing = sync.PushPendingAsync(p.Id, true); await entered.Task; await w.SaveAsync(a, new(p.Id, p.Kind, null, p.Revision, new() { ["name"] = "Newer" })); release.SetResult(); var result = await pushing; Check(result.Acknowledged == 0 && result.Issues.Single().Code == "LOCAL_REVISION_CHANGED" && (await sync.StatusAsync()).Pending.Single().RecordRevision == 2); adapter.BeforePush = null; Check((await sync.PushPendingAsync(p.Id, true)).Acknowledged == 1); } });
        await Run("wrong acknowledgement keeps durable entry and safe error codes hide remote bodies", async () => { var (w, a) = await Setup("ack"); using (w) { var p = await w.SaveAsync(a, Draft("projects", "P")); var adapter = new IsolatedLoopbackSyncAdapter([new(a.Id, p.Id)], true) { RewriteAcknowledgement = x => x with { Id = "foreign" } }; using var sync = new WorkspaceSyncService(w, a, adapter, true); Check((await sync.PushPendingAsync(p.Id, true)).Issues.Single().Code == "ACK_MISMATCH"); adapter.BeforePush = (_, _) => Task.FromException(new Exception("SECRET-BODY-NOT-LOGGED")); Check((await sync.PushPendingAsync(p.Id, true)).Issues.Single().Code == "SYNC_REMOTE_ERROR" && (await sync.StatusAsync()).Pending.Count == 1); } });
        await Run("explicit logical deletion emits delete rather than missing upsert", async () => { var (w, a) = await Setup("delete"); using (w) { var p = await w.SaveAsync(a, Draft("projects", "P")); await w.DeleteAsync(a, p.Kind, p.Id, p.Revision, true); var adapter = new IsolatedLoopbackSyncAdapter([new(a.Id, p.Id)], true); using var sync = new WorkspaceSyncService(w, a, adapter, true); Check((await sync.PushPendingAsync(p.Id, true)).Acknowledged == 1); Check((await adapter.FetchAsync(new(a.Id, p.Id), SyncTable.Projects, default)).Records.Single().Deleted); } });
        await Run("cancellation and service lifetime stop await without acknowledging pending queue", async () => { var (w, a) = await Setup("cancel"); using (w) { var p = await w.SaveAsync(a, Draft("projects", "P")); var entered = new TaskCompletionSource(); var adapter = new IsolatedLoopbackSyncAdapter([new(a.Id, p.Id)], true) { BeforePush = async (_, ct) => { entered.TrySetResult(); await Task.Delay(Timeout.Infinite, ct); } }; using var sync = new WorkspaceSyncService(w, a, adapter, true); using var ct = new CancellationTokenSource(); var pushing = sync.PushPendingAsync(p.Id, true, ct.Token); await entered.Task; ct.Cancel(); await Cancelled(pushing); Check((await sync.StatusAsync()).Pending.Count == 1); var pending = sync.PushPendingAsync(p.Id, true); sync.Dispose(); await Cancelled(pending); using var other = new WorkspaceSyncService(w, a); Check((await other.StatusAsync()).Pending.Count == 1); } });
        await Run("locked atomic save and cancelled feature save change neither queue nor business row", async () => { var (w, a) = await Setup("atomic"); using (w) { var p = await w.SaveAsync(a, Draft("projects", "P")); var path = Path.Combine(w.DataRoot, "workspace.json"); var before = File.ReadAllBytes(path); using (var held = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read)) { try { await w.SaveAsync(a, new(p.Id, p.Kind, null, p.Revision, new() { ["name"] = "Failed" })); throw new Exception("Expected IO rejection"); } catch (IOException) { } } Check(before.SequenceEqual(File.ReadAllBytes(path))); await Cancelled(w.SaveAsync(a, Draft("tasks", "Cancelled"), new(true))); Check(before.SequenceEqual(File.ReadAllBytes(path))); } });
        await Run("tampered queued record binding rejected before transport", async () => { var (w, a) = await Setup("binding"); var p = await w.SaveAsync(a, Draft("projects", "P")); var path = w.DataRoot; w.Dispose(); var file = Path.Combine(path, "workspace.json"); var doc = JsonNode.Parse(File.ReadAllText(file))!; doc["SyncOutbox"]![0]!["RecordRevision"] = 99; File.WriteAllText(file, doc.ToJsonString()); using var reopened = new LocalWorkspace(path); Schemas(reopened); var actor = await reopened.LoginAsync("Local owner", "synthetic-password-70"); var adapter = new IsolatedLoopbackSyncAdapter([new(actor.Id, p.Id)], true); using var sync = new WorkspaceSyncService(reopened, actor, adapter, true); Check((await sync.PushPendingAsync(p.Id, true)).Issues.Single().Code == "SYNC_RECORD_MISMATCH" && adapter.DeliveryAttempts == 0); });
        await Run("new-copy import does not silently enqueue historical imported records and rollback retains earlier queue", async () => { var (w, a) = await Setup("import"); using (w) using (var sync = new WorkspaceSyncService(w, a)) { await w.SaveAsync(a, Draft("projects", "Original")); var package = Path.Combine(work, "local-export.zip"); await w.ExportAsync(a, package); var preview = await w.PreviewImportAsync(a, package); await w.ImportAsync(a, preview, true); Check((await w.ListAsync(a, new RecordQuery("projects"))).Count == 2 && (await sync.StatusAsync()).Pending.Count == 1); await w.RollbackLastImportAsync(a, true); Check((await w.ListAsync(a, new RecordQuery("projects"))).Count == 1 && (await sync.StatusAsync()).Pending.Count == 1); } });
        await Run("disabled actor during transport cannot clear queue and fresh authorized retry can recover", async () => { var (w, a) = await Setup("revoked-inflight"); using (w) { var p = await w.SaveAsync(a, Draft("projects", "P")); var info = await w.SaveUserAsync(a, null, "Editor", "editor", [p.Id], false, "editor-password-70"); var e = await w.LoginAsync("Editor", "editor-password-70"); await w.SaveAsync(e, Draft("processes", "Own", p.Id)); var entered = new TaskCompletionSource(); var release = new TaskCompletionSource(); var adapter = new IsolatedLoopbackSyncAdapter([new(e.Id, p.Id)], true) { BeforePush = async (_, ct) => { entered.SetResult(); await release.Task.WaitAsync(ct); } }; using var sync = new WorkspaceSyncService(w, e, adapter, true); var pending = sync.PushPendingAsync(p.Id, true); await entered.Task; await w.SaveUserAsync(a, info.Id, "Editor", "editor", [p.Id], true, null); release.SetResult(); var result = await pending; Check(result.Acknowledged == 0 && result.Issues.Single().Code == "UNAUTHENTICATED"); await Expect("UNAUTHENTICATED", () => sync.StatusAsync()); await w.SaveUserAsync(a, info.Id, "Editor", "editor", [p.Id], false, null); var fresh = await w.LoginAsync("Editor", "editor-password-70"); using var retry = new WorkspaceSyncService(w, fresh, adapter, true); adapter.BeforePush = null; Check((await retry.StatusAsync()).Pending.Count == 1 && (await retry.PushPendingAsync(p.Id, true)).Acknowledged == 1 && adapter.AppliedMutations == 1); } });
        await Run("concurrent feature pushes serialize exact current queue without duplicate mutation", async () => { var (w, a) = await Setup("parallel-push"); using (w) { var p = await w.SaveAsync(a, Draft("projects", "P")); var entered = new TaskCompletionSource(); var release = new TaskCompletionSource(); var adapter = new IsolatedLoopbackSyncAdapter([new(a.Id, p.Id)], true) { BeforePush = async (_, ct) => { entered.SetResult(); await release.Task.WaitAsync(ct); } }; using var sync = new WorkspaceSyncService(w, a, adapter, true); var one = sync.PushPendingAsync(p.Id, true); await entered.Task; var two = sync.PushPendingAsync(p.Id, true); release.SetResult(); var both = await Task.WhenAll(one, two); Check(both.Sum(x => x.Acknowledged) == 1 && adapter.DeliveryAttempts == 1); sync.Dispose(); sync.Dispose(); } });
        await SourceTests();
        await SchedulerTests();
        var output = new { feature = "WorkspaceSync70", pass, fail, work, networkCalls = 0, companyDataUsed = false, reportReady = false, supervisorAccepted = false, tests = results };
        await File.WriteAllTextAsync(Path.Combine(work, "RESULT.json"), JsonSerializer.Serialize(output, new JsonSerializerOptions { WriteIndented = true })); Console.WriteLine($"WORKSPACE_SYNC70 pass={pass} fail={fail} evidence={work}"); return fail == 0 ? 0 : 1;
    }
}
